    serviceType,
    namespace,
    name,
    description,
    ports,
    clusterIP,
    loadBalancerIP,
    externalIPs,
    selectors,
    sessionAffinity,
    sessionAffinityTimeout,
    labels,
    annotations,
    navigate,
