import { useState, useEffect } from 'react';
import { Drawer, Button, Input, Textarea, FormField } from '@/design-system';
import { HStack, VStack } from '@/design-system/layouts';

/* ----------------------------------------
   Types
   ---------------------------------------- */

export interface RoleData {
  name: string;
  description: string;
}

export interface EditRoleDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  initialData?: RoleData;
  onSubmit?: (data: RoleData) => void;
}

/* ----------------------------------------
   EditRoleDrawer Component
   ---------------------------------------- */

export function EditRoleDrawer({
  isOpen,
  onClose,
  initialData = {
    name: 'Member',
    description: '',
  },
  onSubmit,
}: EditRoleDrawerProps) {
  const [name, setName] = useState(initialData.name);
  const [description, setDescription] = useState(initialData.description);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasAttemptedSubmit, setHasAttemptedSubmit] = useState(false);
  const [nameError, setNameError] = useState<string | null>(null);
  const [descriptionError, setDescriptionError] = useState<string | null>(null);

  // Reset state when drawer opens
  useEffect(() => {
    if (isOpen) {
      setName(initialData.name);
      setDescription(initialData.description);
      setHasAttemptedSubmit(false);
      setNameError(null);
      setDescriptionError(null);
    }
  }, [isOpen, initialData]);

  const handleSubmit = async () => {
    setHasAttemptedSubmit(true);
    let hasError = false;

    if (!name.trim()) {
      setNameError('Please enter a role name.');
      hasError = true;
    } else if (name.trim().length < 2 || name.trim().length > 128) {
      setNameError('Name must be between 2-128 characters.');
      hasError = true;
    } else {
      setNameError(null);
    }

    if (description.length > 255) {
      setDescriptionError('Description must be 255 characters or less.');
      hasError = true;
    } else {
      setDescriptionError(null);
    }

    if (hasError) return;

    setIsSubmitting(true);
    try {
      await onSubmit?.({
        name: name.trim(),
        description: description.trim(),
      });
      onClose();
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setName(initialData.name);
    setDescription(initialData.description);
    setHasAttemptedSubmit(false);
    setNameError(null);
    setDescriptionError(null);
    onClose();
  };

  return (
    <Drawer
      isOpen={isOpen}
      onClose={handleClose}
      title="Edit role"
      description="Edit basic information for this role."
      width={360}
      footer={
        <HStack gap={2} justify="center" className="w-full">
          <Button variant="secondary" onClick={handleClose} className="flex-1">
            Cancel
          </Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={isSubmitting}
            className="flex-1"
          >
            {isSubmitting ? 'Saving...' : 'Save'}
          </Button>
        </HStack>
      }
    >
      <VStack gap={6} className="pb-6">
        {/* Header */}

        {/* Role name field */}
        <FormField required error={!!nameError}>
          <FormField.Label>Role name</FormField.Label>
          <FormField.Control>
            <Input
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                if (nameError) setNameError(null);
              }}
              placeholder="Enter role name"
              fullWidth
              error={!!nameError}
            />
          </FormField.Control>
          <FormField.ErrorMessage>{nameError}</FormField.ErrorMessage>
          <FormField.HelperText>
            You can use letters, numbers, and special characters (+=,.@-_), and the length must be
            between 2-128 characters.
          </FormField.HelperText>
        </FormField>

        {/* Description field */}
        <FormField error={!!descriptionError}>
          <FormField.Label>Description</FormField.Label>
          <FormField.Control>
            <Textarea
              value={description}
              onChange={(e) => {
                setDescription(e.target.value);
                if (descriptionError) setDescriptionError(null);
              }}
              placeholder="Enter description"
              fullWidth
              rows={3}
              error={!!descriptionError}
            />
          </FormField.Control>
          <FormField.ErrorMessage>{descriptionError}</FormField.ErrorMessage>
          <FormField.HelperText>
            You can use letters, numbers, and special characters (+=,.@-_()[]), and maximum 255
            characters.
          </FormField.HelperText>
        </FormField>
      </VStack>
    </Drawer>
  );
}

export default EditRoleDrawer;
