import React, { useState, useRef, useCallback, useEffect } from 'react';
import { IconX, IconExternalLink, IconTerminal2 } from '@tabler/icons-react';
import { Select, Button } from '@/design-system';

/* ----------------------------------------
   Types
   ---------------------------------------- */

export type ConnectionStatus = 'connected' | 'connecting' | 'disconnected';

export interface ShellTab {
  id: string;
  title: string;
  content: string;
  connectionStatus: ConnectionStatus;
  instanceId?: string;
  container?: string;
}

export interface ShellPanelProps {
  /** Whether the shell panel is expanded */
  isExpanded: boolean;
  /** Callback when panel expand state changes */
  onExpandedChange: (expanded: boolean) => void;
  /** Active tabs */
  tabs: ShellTab[];
  /** Active tab id */
  activeTabId: string | null;
  /** Callback when active tab changes */
  onActiveTabChange: (tabId: string) => void;
  /** Callback to close a tab */
  onCloseTab: (tabId: string) => void;
  /** Callback to add new tab */
  onAddTab?: () => void;
  /** Callback when content changes */
  onContentChange?: (tabId: string, content: string) => void;
  /** Callback when clear button is clicked */
  onClear?: (tabId: string) => void;
  /** Callback when open in new tab is clicked */
  onOpenInNewTab?: (tab: ShellTab) => void;
  /** Initial height of the panel */
  initialHeight?: number;
  /** Minimum height of the panel */
  minHeight?: number;
  /** Whether the sidebar is open */
  sidebarOpen?: boolean;
  /** Width of the sidebar in pixels (used for positioning) */
  sidebarWidth?: number;
}

/* ----------------------------------------
   Connection Status Indicator
   ---------------------------------------- */

function ConnectionStatusIndicator({ status }: { status: ConnectionStatus }) {
  const statusConfig = {
    connected: {
      color: 'bg-emerald-500',
      label: 'Connected',
    },
    connecting: {
      color: 'bg-amber-500',
      label: 'Connecting',
    },
    disconnected: {
      color: 'bg-red-500',
      label: 'Disconnected',
    },
  };

  const config = statusConfig[status];

  return (
    <div className="flex items-center gap-1.5 ml-3">
      <span className={`size-2 rounded-full ${config.color}`} />
      <span className="text-body-md text-[var(--color-text-default)]">{config.label}</span>
    </div>
  );
}

/* ----------------------------------------
   Shell Tab Button
   ---------------------------------------- */

interface ShellTabButtonProps {
  tab: ShellTab;
  isActive: boolean;
  onClick: () => void;
  onClose: () => void;
  onOpenInNewTab?: () => void;
}

function ShellTabButton({ tab, isActive, onClick, onClose, onOpenInNewTab }: ShellTabButtonProps) {
  return (
    <div
      className={`
        relative flex items-center gap-2 px-3 h-9 cursor-pointer transition-colors border-r border-[var(--color-border-subtle)]
        ${
          isActive
            ? 'bg-[var(--color-surface-default)]'
            : 'bg-[var(--color-surface-subtle)] hover:bg-[var(--color-surface-muted)]'
        }
      `}
      onClick={onClick}
    >
      {/* Active indicator */}
      {isActive && (
        <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-[var(--color-action-primary)]" />
      )}
      <IconTerminal2
        size={14}
        className={isActive ? 'text-[var(--color-text-default)]' : 'text-[var(--color-text-muted)]'}
        stroke={1.5}
      />
      <span
        className={`flex-1 truncate text-[length:var(--tabbar-font-size)] leading-[var(--tabbar-line-height)] font-medium max-w-[140px] ${isActive ? 'text-[var(--color-text-default)]' : 'text-[var(--color-text-muted)]'}`}
      >
        {tab.title}
      </span>
      <button
        onClick={(e) => {
          e.stopPropagation();
          onOpenInNewTab?.();
        }}
        className="p-0.5 rounded hover:bg-[var(--color-surface-muted)] transition-colors text-[var(--color-text-muted)] hover:text-[var(--color-text-default)] cursor-pointer"
        title="Open in new tab"
      >
        <IconExternalLink size={12} stroke={1.5} />
      </button>
      <button
        onClick={(e) => {
          e.stopPropagation();
          onClose();
        }}
        className="p-0.5 rounded hover:bg-[var(--color-surface-muted)] transition-colors text-[var(--color-text-muted)] hover:text-[var(--color-text-default)] cursor-pointer"
        title="Close tab"
      >
        <IconX size={12} stroke={1} />
      </button>
    </div>
  );
}

/* ----------------------------------------
   Shell Panel Component
   ---------------------------------------- */

export function ShellPanel({
  isExpanded,
  onExpandedChange: _onExpandedChange,
  tabs,
  activeTabId,
  onActiveTabChange,
  onCloseTab,
  onContentChange,
  onClear,
  onOpenInNewTab,
  initialHeight = 350,
  minHeight = 300,
  sidebarOpen = true,
  sidebarWidth,
}: ShellPanelProps) {
  const [height, setHeight] = useState(initialHeight);
  const [isResizing, setIsResizing] = useState(false);
  const [selectedContainer, setSelectedContainer] = useState('container-0');
  const contentRef = useRef<HTMLDivElement>(null);

  const activeTab = tabs.find((t) => t.id === activeTabId);

  // Container options for Select
  const containerOptions = [
    { value: 'container-0', label: 'Container: container-0' },
    { value: 'container-1', label: 'Container: container-1' },
    { value: 'container-2', label: 'Container: container-2' },
  ];

  // Calculate max height (content area height - 100px)
  const getMaxHeight = useCallback(() => {
    if (typeof window === 'undefined') return 600;
    const mainContent = document.querySelector('main');
    if (mainContent) {
      return mainContent.clientHeight - 100;
    }
    return window.innerHeight - 200;
  }, []);

  // Handle resize
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  useEffect(() => {
    if (!isResizing) return;

    // Prevent text selection during resize
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'ns-resize';

    const handleMouseMove = (e: MouseEvent) => {
      const maxHeight = getMaxHeight();
      const newHeight = window.innerHeight - e.clientY;
      setHeight(Math.min(Math.max(newHeight, minHeight), maxHeight));
    };

    const handleMouseUp = () => {
      setIsResizing(false);
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    };
  }, [isResizing, minHeight, getMaxHeight]);

  // Auto-scroll to bottom when content changes
  useEffect(() => {
    if (contentRef.current && activeTab) {
      contentRef.current.scrollTop = contentRef.current.scrollHeight;
    }
  }, [activeTab?.content]);

  // Handle clear
  const handleClear = useCallback(() => {
    if (activeTabId) {
      onContentChange?.(activeTabId, '');
      onClear?.(activeTabId);
    }
  }, [activeTabId, onContentChange, onClear]);

  // Don't render anything if no tabs or not expanded
  if (!isExpanded || tabs.length === 0) {
    return null;
  }

  return (
    <div
      className="fixed bottom-0 right-0 z-40 bg-[var(--color-surface-default)] border-t border-l border-[var(--color-border-default)] shadow-lg flex flex-col"
      style={{
        height: `${height}px`,
        left: sidebarWidth !== undefined ? `${sidebarWidth}px` : sidebarOpen ? '200px' : '0px',
        transition: isResizing ? 'none' : 'left 0.2s ease-out, height 0.1s ease-out',
      }}
    >
      {/* Resize Handle */}
      <div
        className="absolute -top-1 left-0 right-0 h-2 cursor-ns-resize"
        onMouseDown={handleMouseDown}
      />

      {/* Tab Bar - White tone */}
      <div className="flex items-center bg-[var(--color-surface-subtle)]">
        {/* Tabs */}
        <div className="flex items-center overflow-x-auto scrollbar-none">
          {tabs.map((tab) => (
            <ShellTabButton
              key={tab.id}
              tab={tab}
              isActive={tab.id === activeTabId}
              onClick={() => onActiveTabChange(tab.id)}
              onClose={() => onCloseTab(tab.id)}
              onOpenInNewTab={() => onOpenInNewTab?.(tab)}
            />
          ))}
        </div>
      </div>

      {/* Content - Dark background for logs */}
      <div
        ref={contentRef}
        className="flex-1 overflow-auto p-4 font-mono text-body-md leading-5 bg-[#0d1117] text-slate-300 shell-scroll"
      >
        {activeTab ? (
          activeTab.content ? (
            <pre className="whitespace-pre-wrap break-all m-0">{activeTab.content}</pre>
          ) : (
            <span className="text-slate-600">No output</span>
          )
        ) : (
          <div className="flex items-center justify-center h-full text-slate-600">
            No console selected
          </div>
        )}
      </div>

      {/* Bottom Status Bar - White tone */}
      <div className="flex items-center justify-between px-3 py-2 border-t border-[var(--color-border-default)] bg-[var(--color-surface-subtle)]">
        <div className="flex items-center gap-1">
          {/* Container Select - Using Design System */}
          <Select
            value={selectedContainer}
            onChange={setSelectedContainer}
            options={containerOptions}
            placeholder="Container"
            size="sm"
          />

          {/* Clear Button - Using Design System */}
          <Button size="sm" variant="secondary" onClick={handleClear}>
            Clear
          </Button>

          {/* Connection Status */}
          {activeTab && <ConnectionStatusIndicator status={activeTab.connectionStatus} />}
        </div>
      </div>
    </div>
  );
}

/* ----------------------------------------
   Hook for managing shell tabs
   ---------------------------------------- */

export interface UseShellPanelOptions {
  initialExpanded?: boolean;
}

export function useShellPanel(options: UseShellPanelOptions = {}) {
  const [isExpanded, setIsExpanded] = useState(options.initialExpanded ?? false);
  const [tabs, setTabs] = useState<ShellTab[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>(null);

  const openConsole = useCallback(
    (instanceId: string, instanceName: string) => {
      // Check if tab already exists
      const existingTab = tabs.find((t) => t.instanceId === instanceId);
      if (existingTab) {
        setActiveTabId(existingTab.id);
        setIsExpanded(true);
        return;
      }

      // Create new tab
      const newTab: ShellTab = {
        id: `console-${instanceId}-${Date.now()}`,
        title: instanceName,
        content: '',
        connectionStatus: 'connecting',
        instanceId,
        container: 'container-0',
      };

      setTabs((prev) => [...prev, newTab]);
      setActiveTabId(newTab.id);
      setIsExpanded(true);

      // Simulate connection and logs
      setTimeout(() => {
        const sampleLogs = generateSampleLogs(instanceName);
        setTabs((prev) =>
          prev.map((t) =>
            t.id === newTab.id
              ? { ...t, connectionStatus: 'connected' as ConnectionStatus, content: sampleLogs }
              : t
          )
        );
      }, 1000);
    },
    [tabs]
  );

  const closeTab = useCallback(
    (tabId: string) => {
      setTabs((prev) => {
        const newTabs = prev.filter((t) => t.id !== tabId);

        // If closing active tab, switch to another
        if (activeTabId === tabId && newTabs.length > 0) {
          setActiveTabId(newTabs[newTabs.length - 1].id);
        } else if (newTabs.length === 0) {
          setActiveTabId(null);
          setIsExpanded(false);
        }

        return newTabs;
      });
    },
    [activeTabId]
  );

  const updateContent = useCallback((tabId: string, content: string) => {
    setTabs((prev) => prev.map((t) => (t.id === tabId ? { ...t, content } : t)));
  }, []);

  const clearContent = useCallback((tabId: string) => {
    setTabs((prev) => prev.map((t) => (t.id === tabId ? { ...t, content: '' } : t)));
  }, []);

  return {
    isExpanded,
    setIsExpanded,
    tabs,
    activeTabId,
    setActiveTabId,
    openConsole,
    closeTab,
    updateContent,
    clearContent,
  };
}

