import { useState, useEffect } from 'react';
import { Drawer, Button, Toggle, FormField, InfoBox } from '@/design-system';
import { HStack, VStack } from '@/design-system/layouts';

export interface InstanceInfo {
  id: string;
  name: string;
  isLocked?: boolean;
}

export interface LockSettingDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  instance: InstanceInfo | null;
  onSubmit?: (isLocked: boolean) => void;
}

export function LockSettingDrawer({ isOpen, onClose, instance, onSubmit }: LockSettingDrawerProps) {
  const [isLocked, setIsLocked] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (isOpen && instance) {
      setIsLocked(instance.isLocked ?? false);
    }
  }, [isOpen, instance]);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    try {
      await onSubmit?.(isLocked);
      onClose();
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    onClose();
  };

  return (
    <Drawer
      isOpen={isOpen}
      onClose={handleClose}
      title="Lock setting"
      width={360}
      footer={
        <HStack gap={2} className="w-full">
          <Button variant="secondary" onClick={handleClose} className="flex-1 h-8">
            Cancel
          </Button>
          <Button
            variant="primary"
            onClick={handleSubmit}
            disabled={isSubmitting}
            className="flex-1 h-8"
          >
            {isSubmitting ? 'Saving...' : 'Save'}
          </Button>
        </HStack>
      }
    >
      <VStack gap={6}>
        {/* Header */}

        {/* Instance Info */}
        {instance && <InfoBox label="Instance" value={instance.name} />}

        {/* Lock Status */}
        <FormField
          label="Lock status"
          description="When locked, the instance cannot be modified or deleted."
          spacing="loose"
        >
          <HStack gap={2} align="center">
            <Toggle checked={isLocked} onChange={setIsLocked} />
            <span className="text-body-md text-[var(--color-text-default)] leading-4">
              {isLocked ? 'Locked' : 'Unlocked'}
            </span>
          </HStack>
        </FormField>
      </VStack>
    </Drawer>
  );
}

export default LockSettingDrawer;
